{"command":"python3 -c "
import csv
with open('outputs/t08_pois_clean.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    qids = set()
    empty_labels = []
    for row in reader:
        qid = row['qid']
        label = row['label']
        lat = float(row['latitude'])
        lon = float(row['longitude'])

        if qid in qids:
            print(f'Duplicate qid: {qid}')
        qids.add(qid)

        if not label:
            empty_labels.append(qid)

        if not (-90 <= lat <= 90):
            print(f'Invalid latitude: {lat} for {qid}')
        if not (-180 <= lon <= 180):
            print(f'Invalid longitude: {lon} for {qid}')

    if empty_labels:
        print(f'Empty labels for: {empty_labels}')
    else:
        print('All labels are non-empty')

    print(f'Total unique qids: {len(qids)}')
""}
